      const [rewards] = await conn.query(`SELECT r.*, p.positionCode FROM stake_rewards r JOIN stake_positions p ON p.id=r.positionId WHERE r.userId=? ORDER BY r.postedAt DESC LIMIT 50`, [userId]);
