var miningWorkerUserCursor = 0;
async function runMiningWorkerCycle() {
  return withMiningConnection(async (conn) => {
    const settledBoostRewards = await settleDuePendingBoostRewards(conn);
    let [users2] = await conn.query(`SELECT DISTINCT cp.userId FROM mining_customer_packages cp
      WHERE cp.status='active' AND cp.startsAt<UTC_TIMESTAMP(3) AND (cp.expiresAt IS NULL OR cp.expiresAt>UTC_TIMESTAMP(3)) AND cp.userId>? ORDER BY cp.userId LIMIT 100`, [miningWorkerUserCursor]);
    if (!users2.length && miningWorkerUserCursor) {
      miningWorkerUserCursor = 0;
      [users2] = await conn.query(`SELECT DISTINCT cp.userId FROM mining_customer_packages cp
        WHERE cp.status='active' AND cp.startsAt<UTC_TIMESTAMP(3) AND (cp.expiresAt IS NULL OR cp.expiresAt>UTC_TIMESTAMP(3)) ORDER BY cp.userId LIMIT 100`);
    }
    if (users2.length) miningWorkerUserCursor = Number(users2[users2.length - 1].userId);
    let intervals = 0;
    for (const row of users2) intervals += await accrueOneUser(conn, Number(row.userId), 30);
    const [jobs] = await conn.query(`SELECT id FROM mining_conversion_jobs WHERE status IN ('queued','retrying') AND availableAt<=UTC_TIMESTAMP(3) ORDER BY id LIMIT 50`);
    const outcomes = { completed: 0, waiting: 0, retrying: 0, skipped: 0 };
    for (const row of jobs) {
      const status = await processConversionJob(conn, Number(row.id));
      if (status in outcomes) outcomes[status]++;
    }
    return { usersProcessed: users2.length, intervalsProcessed: intervals, settledBoostRewards, conversionJobs: outcomes };
  });
}
async function runMiningAccrualForCustomer(userId) {
  return withMiningConnection(async (conn) => accrueOneUser(conn, userId, 120));
}

