async function listMiningAdminCustomers(input) {
  const limit = Math.max(1, Math.min(100, Number(input.limit || 50)));
  const query = String(input.query || "").trim();
  return withMiningConnection(async (conn) => {
    const pattern = `%${query.replace(/[\\%_]/g, "\\$&")}%`;
    const [rows2] = await conn.query(`SELECT u.id,u.name,u.email,u.createdAt,u.lastSignedIn,COALESCE(c.accountStatus,'active') accountStatus,c.riskTier,c.updatedAt controlUpdatedAt,
      (SELECT COUNT(*) FROM mining_customer_packages cp WHERE cp.userId=u.id AND cp.status='active' AND (cp.expiresAt IS NULL OR cp.expiresAt>UTC_TIMESTAMP(3))) activePackages,
      (SELECT COALESCE(SUM(tokenAmount),0) FROM mining_reward_events r WHERE r.userId=u.id) totalSimulatedTokens
      FROM users u LEFT JOIN customer_controls c ON c.userId=u.id
      WHERE u.role='user' AND (?='' OR u.email LIKE ? OR u.name LIKE ? OR CAST(u.id AS CHAR)=?)
      ORDER BY u.createdAt DESC LIMIT ?`, [query, pattern, pattern, query, limit]);
    return rows2.map((row) => ({ userId: Number(row.id), name: row.name || "", email: row.email || "", createdAt: byDate(row.createdAt), lastSignedIn: byDate(row.lastSignedIn), accountStatus: row.accountStatus, riskTier: row.riskTier || "standard", controlUpdatedAt: byDate(row.controlUpdatedAt), activePackages: Number(row.activePackages || 0), totalSimulatedTokens: String(row.totalSimulatedTokens || "0") }));
  });
}
