async function createMiningAdjustment(adminId, input) {
  const asset = assertMiningAsset(input.assetCode);
  const amount = exactAmount(input.amount, asset, "Adjustment amount");
  const reason = requiredReason(input.reason);
  const key = requestKey("mining-adjustment", adminId, input.idempotencyKey);
  return withMiningConnection(async (conn) => inMiningTransaction(conn, async () => {
    const [existing] = await conn.query(`SELECT id,userId,assetCode,amount,direction,status,ledgerTransactionId FROM mining_adjustment_requests WHERE idempotencyKey=? LIMIT 1`, [key]);
    if (existing[0]) return { requestId: Number(existing[0].id), userId: Number(existing[0].userId), asset: existing[0].assetCode, amount: String(existing[0].amount), direction: existing[0].direction, status: existing[0].status, ledgerTransactionId: existing[0].ledgerTransactionId ? Number(existing[0].ledgerTransactionId) : null, idempotent: true };
    const [users2] = await conn.query(`SELECT id,role,loginMethod FROM users WHERE id=? LIMIT 1 FOR UPDATE`, [input.userId]);
    if (!users2[0] || users2[0].role !== "user" || users2[0].loginMethod === "closed") throw new MiningError("Customer was not found or is closed");
    await ensureMiningCheckpoint(conn, input.userId);
    const config2 = await loadMiningConfig(conn);
    let usdValue = null;
    let approvalRequired = false;
    try {
      const rate = await getMiningAssetRate(conn, asset, config2);
      usdValue = amount.times(rate.usdPerUnit);
      approvalRequired = usdValue.gt(config2.dualApprovalThresholdUsd);
    } catch {
      approvalRequired = true;
    }
    const [request] = await conn.execute(`INSERT INTO mining_adjustment_requests (userId,assetCode,amount,direction,reason,status,requestedBy,idempotencyKey) VALUES (?,?,?,?,?,?,?,?)`, [input.userId, asset, amount.toString(), input.direction, reason, approvalRequired ? "pending" : "posted", adminId, key]);
    const requestId = Number(request.insertId);
    let ledgerId = null;
    let reference = null;
    if (!approvalRequired) {
      const signed = input.direction === "credit" ? amount : amount.negated();
      const transaction = await createMiningLedgerTransaction(conn, { userId: input.userId, actorUserId: adminId, transactionType: "adjustment", idempotencyKey: `mining-adjustment-tx:${requestId}`, reason, metadata: { requestId, asset, amount: amount.toString(), direction: input.direction, usdValue: usdValue?.toString() || null, simulationOnly: true } });
      await postMiningLedgerEntries(conn, transaction, [{ userId: input.userId, asset, amount: signed, entryType: `mining_adjustment_${input.direction}` }, { userId: 0, asset, amount: signed.negated(), entryType: "mining_adjustment_clearing" }]);
      ledgerId = transaction.id;
      reference = transaction.referenceCode;
      await conn.execute(`UPDATE mining_adjustment_requests SET ledgerTransactionId=?,resolvedAt=UTC_TIMESTAMP(3) WHERE id=?`, [ledgerId, requestId]);
      await createMiningNotification(conn, input.userId, "Mining balance adjustment posted", `An administrator posted a simulated ${input.direction} of ${amount.toString()} ${asset}. Reference ${reference}.`, `mining-adjustment-posted:${requestId}`);
    }
    await writeMiningAudit(conn, { actorUserId: adminId, action: approvalRequired ? "mining.adjustment.approval_requested" : "mining.adjustment.posted", entityType: "mining_adjustment_request", entityId: String(requestId), reason, metadata: { userId: input.userId, asset, amount: amount.toString(), direction: input.direction, usdValue: usdValue?.toString() || null, dualApprovalThresholdUsd: config2.dualApprovalThresholdUsd } });
    return { requestId, userId: input.userId, asset, amount: amount.toString(), direction: input.direction, status: approvalRequired ? "pending" : "posted", requiresSecondAdminApproval: approvalRequired, usdValue: usdValue?.toString() || null, ledgerTransactionId: ledgerId, reference };
  }));
}
