function resolveTrustedProxyHops(value) {
  const raw = value?.trim();
  if (!raw) return false;
  if (!/^\d+$/.test(raw)) return false;
  const hops = Number(raw);
  if (!Number.isSafeInteger(hops) || hops < 0 || hops > 10) return false;
  return hops === 0 ? false : hops;
}

